type principalKey struct{}
func withPrincipal(ctx context.Context, id string) context.Context {
    return context.WithValue(ctx, principalKey{}, id)
}
func handleApprove(w http.ResponseWriter, r *http.Request) {
    who, _ := r.Context().Value(principalKey{}).(string)   // verified principal, not the body
    res, err := db.ExecContext(r.Context(),
        `UPDATE requests SET approved_by = $2
          WHERE id = $1 AND status = 'initiated' AND initiated_by <> $2`, r.PathValue("id"), who)
    if err != nil || mustAffected(res) == 0 { http.Error(w, "not approvable", http.StatusConflict); return }
    w.WriteHeader(http.StatusNoContent)
}
